From 377c7cb22f159995ce9e1b8324913206a7e2f3d7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:12:02 +0100
Subject: [PATCH] ksldapp: Kill a greeter that doesn't exit after a grace time
 unlock

An unlock in grace time only sends SIGTERM to the greeter. If it doesn't
exit, the next lock can't start a new greeter and leaves a black screen,
so kill it after two seconds, or right away when the screen locks again.

BUG: 528681
---
 ksldapp.cpp | 38 +++++++++++++++++++++++++++++++++++---
 ksldapp.h   |  7 +++++++
 2 files changed, 42 insertions(+), 3 deletions(-)

diff --git a/ksldapp.cpp b/ksldapp.cpp
index 2e83b2ac..b6d17787 100644
--- a/ksldapp.cpp
+++ b/ksldapp.cpp
@@ -100,6 +100,7 @@ void KSldApp::cleanUp()
 static bool s_graceTimeKill = false;
 static bool s_logindExit = false;
 static bool s_lockProcessRequestedExit = false;
+static constexpr std::chrono::milliseconds s_greeterTerminateTimeout = std::chrono::seconds(2);

 void KSldApp::initialize()
 {
@@ -168,6 +169,16 @@ void KSldApp::initialize()
     connect(m_lockProcess, finishedSignal, this, [this](int exitCode, QProcess::ExitStatus exitStatus) {
         qCDebug(KSCREENLOCKER) << "Greeter process exitted with status:" << exitStatus << "exit code:" << exitCode;

+        if (m_pendingLockProcess) {
+            qCDebug(KSCREENLOCKER) << "Previous greeter process is gone, starting the new one";
+            const EstablishLock establishLock = *m_pendingLockProcess;
+            m_pendingLockProcess.reset();
+            s_graceTimeKill = false;
+            s_logindExit = false;
+            startLockProcess(establishLock);
+            return;
+        }
+
         if (s_lockProcessRequestedExit) {
             qCDebug(KSCREENLOCKER) << "Lock process had requested exit; we already did the unlock process elsewhere";
             return;
@@ -232,7 +243,7 @@ void KSldApp::initialize()
     });
     connect(m_logind, &LogindIntegration::requestUnlock, this, [this]() {
         if (lockState() == Locked) {
-            if (m_lockProcess->state() != QProcess::NotRunning) {
+            if (m_lockProcess->state() != QProcess::NotRunning && !m_pendingLockProcess) {
                 s_logindExit = true;
                 m_lockProcess->terminate();
             } else {
@@ -324,8 +335,12 @@ void KSldApp::lock(EstablishLock establishLock)
         // but make sure it's really locked
         endGraceTime();
         if (establishLock == EstablishLock::Immediate) {
-            // signal the greeter to switch to immediateLock mode
-            kill(m_lockProcess->processId(), SIGUSR1);
+            if (m_pendingLockProcess) {
+                m_pendingLockProcess = EstablishLock::Immediate;
+            } else {
+                // signal the greeter to switch to immediateLock mode
+                kill(m_lockProcess->processId(), SIGUSR1);
+            }
         }
         return;
     }
@@ -356,6 +371,7 @@ void KSldApp::doUnlock()
 {
     qCDebug(KSCREENLOCKER) << "Unlocking now.";
     m_emergencyLockWindow.reset();
+    m_pendingLockProcess.reset();
     m_lockState = Unlocked;
     m_lockedTimer.invalidate();
     m_greeterCrashedCounter = 0;
@@ -382,6 +398,15 @@ void KSldApp::startLockProcess(EstablishLock establishLock)
 {
     qCDebug(KSCREENLOCKER) << "Starting lock process with establishLock:" << establishLockToString(establishLock);

+    if (m_lockProcess->state() != QProcess::NotRunning) {
+        // The previous greeter has not exited yet, e.g. after an unlock in grace time. QProcess cannot start a new one
+        // while it runs, so kill it and start the new one once it has exited, without blocking the compositor.
+        qCWarning(KSCREENLOCKER) << "Previous greeter process is still running, killing it";
+        m_pendingLockProcess = establishLock;
+        m_lockProcess->kill();
+        return;
+    }
+
     Q_EMIT aboutToStartGreeter();

     QProcessEnvironment env = m_greeterEnv;
@@ -465,6 +490,13 @@ void KSldApp::unlock()
         doUnlock();
         s_graceTimeKill = true;
         m_lockProcess->terminate();
+        // a greeter that does not exit would keep the next lock from starting a new one, so kill it
+        QTimer::singleShot(s_greeterTerminateTimeout, m_lockProcess, [this, pid = m_lockProcess->processId()] {
+            if (m_lockProcess->state() != QProcess::NotRunning && m_lockProcess->processId() == pid) {
+                qCWarning(KSCREENLOCKER) << "Greeter process did not exit after SIGTERM, killing it";
+                m_lockProcess->kill();
+            }
+        });
     }
 }

diff --git a/ksldapp.h b/ksldapp.h
index 44cfa555..715433ea 100644
--- a/ksldapp.h
+++ b/ksldapp.h
@@ -11,6 +11,8 @@ SPDX-License-Identifier: GPL-2.0-or-later
 #include <QElapsedTimer>
 #include <QProcessEnvironment>

+#include <optional>
+
 #include <KScreenLocker/kscreenlocker_export.h>

 // forward declarations
@@ -372,6 +374,11 @@ private:
      */
     int m_greeterCrashedCounter = 0;

+    /**
+     * Set while a previous greeter is being killed; the new greeter is started with this once it has exited.
+     */
+    std::optional<EstablishLock> m_pendingLockProcess;
+
     /**
      * @brief The environment for the greeter process.
      */
